#!/usr/bin/env node
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const OUT = path.join(ROOT, 'output');
const BLOCK = '**** YD001 SOURCE BLOCK ****';
const ENG = '**** ENGLISH ****';
const END = '**** END BLOCK ****';

function patchFile(rel, slug, T) {
  const fp = path.join(OUT, rel);
  const s = fs.readFileSync(fp, 'utf8');
  const applied = new Set();
  const parts = s.split(BLOCK);
  const out = parts.map((block, i) => {
    if (i === 0) return block;
    const slugM = block.match(/^\s*slug: (.+)$/m);
    const seifM = block.match(/^\s*seif: (.+)$/m);
    const markerM = block.match(/^\s*marker: (.+)$/m);
    if (!slugM || slugM[1].trim() !== slug) return BLOCK + block;
    const seif = seifM[1].trim();
    const marker = markerM ? markerM[1].trim() : 'main';
    const key = `${seif}#${marker}`;
    if (!(key in T)) return BLOCK + block;
    const enStart = block.indexOf(ENG);
    const enEnd = block.indexOf(END);
    if (enStart < 0 || enEnd < 0) throw new Error(`ENGLISH/END missing: ${rel} ${key}`);
    const before = block.slice(0, enStart + ENG.length + 1);
    const after = block.slice(enEnd);
    const text = T[key].endsWith('\n') ? T[key] : T[key] + '\n';
    applied.add(key);
    return BLOCK + before + text + after;
  });
  const missing = Object.keys(T).filter((k) => !applied.has(k));
  if (missing.length) throw new Error(`Keys not found in ${rel}: ${missing.join(', ')}`);
  fs.writeFileSync(fp, out.join(''), 'utf8');
  console.log(`OK ${rel} (${applied.size} blocks)`);
}

// --- mechaber (11) ---
patchFile('siman_033/mechaber/part-001.txt', 'mechaber', {
  '1#main': `The law if the lower cheek was removed and if the esophagus was struck/punctured. In it are 11 seifim. If the lower cheek was removed — kosher, provided it can live through hamara and haleta. {Rama: Likewise a bird whose beak was removed, if it can live through hamara and haleta — kosher (Orach Chaim general rule 54 and Rokeach).}`,
  '2#main': `If the upper cheek was removed — treifah according to Rambam, and one is fit to heed his words.`,
  '3#main': `If the esophagus or the esophagus-crop area was punctured into its cavity in any amount — neveilah.`,
  '4#main': `The esophagus has two membranes: if one of them was punctured — kosher; if both were punctured — forbidden, even if a membrane grew over it and sealed; and even if they were punctured not opposite one another — forbidden, if both were punctured from one wind (interpretation: that they happen to face one another) (Beit Yosef in name of Ritva). {Rama: All this applies only when it is clear the puncture came from disease; but if there is concern it was punctured by a thorn — even if only the inner was punctured — treifah, for we are concerned perhaps the outer was also punctured; and the esophagus has no examination from outside (Beit Yosef in name of Tosafot, Rosh, Ran, and Or Zarua).}`,
  '5#main': `These membranes: the outer is red and the inner white; if they were reversed — the outer white and the inner red — treifah; and likewise if both are red or both white — treifah. {Rama: All the more if it has two esophagi or two tracheae — treifah (Rosh responsa klal 20 siman 9).}`,
  '6#main': `The esophagus has no examination from outside regarding derusah, which requires examination, because since it is red the redness of the wound is not discernible on it. What should one do? If it is a bird — examine the trachea from outside [and slaughter it], then turn the esophagus and examine from inside; if it is an animal — it has no remedy. {Rama: And for us, who are not expert in examination — even a bird has no remedy.}`,
  '7#main': `Regarding puncture as well, the esophagus has no examination from outside — only from inside.`,
  '8#main': `A bird that comes before us and its neck is dirty with blood — we are not concerned for doubt of derusah (see above siman 57) to examine the entire cavity; but we are concerned for doubt of puncture to examine the dirty place. {Rama: Some forbid any bird or animal whose neck is dirty with blood, for we are concerned for puncture of the esophagus and we are not expert (Hagahot Ashiri on siman 51 in name of Or Zarua) — and such is the custom.}`,
  '9#main': `If a thorn was found in the esophagus along its length or its width and it is not stuck in it — kosher (if there is no drop of blood on it from outside) (Tur and Hagahot Maimoniyot); but if it is stuck in it — forbidden, even if there is no drop of blood, for we are concerned perhaps the esophagus was punctured and healed and it is not discernible. {Rama: Some permit if there is no drop of blood from outside, for we are not concerned perhaps it healed (Ra'avan, Rosh, and Hagahot Ashiri in name of Sefer HaTerumah); and thus they practiced to be lenient in our city with those geese that are fattened to make fat from them, for there is a remedy in the city to examine after puncture of the esophagus because it is more common than lung adhesions; and they practiced to be lenient when a thorn sits in the esophagus if it is not punctured on both sides or there is no drop of blood from outside; and one must be very careful with this for it is a d'oraisa prohibition; and it would be better not to examine at all and rely on the majority than to examine and be lenient where there is a financial loss.}`,
  '10#main': `If the esophagus separated from the trachea and they dangled apart from one another for the majority of their length — treifah.`,
  '11#main': `A crop whose roof was punctured with a complete opening in any amount — treifah. And what is its roof? That which stretches with the esophagus when the bird extends its neck. But the rest of the crop if punctured is permitted. {Rama: If the crop was removed — treifah (Beit Yosef in name of most poskim), even if enough remained that food can pass from the esophagus to the crop (as implies Ran on siman 51); puncture of the flesh between the crop and gizzard — treifah (end of chapter 40 and Maharil).}`,
});

// --- siftei-kohen (23) ---
patchFile('siman_033/siftei-kohen/part-001.txt', 'siftei-kohen', {
  '1#א': `["If the lower cheek was removed — kosher."] This is in a case where there is no issue of removal of signs, as above siman 24 seif 15 and Taz:`,
  '1#ב': `["Through hamara and haleta."] See Tur Orach Chaim siman 326:`,
  '2#_': `Treifah according to Rambam. And he gave a reason: the upper cheek was created in animals to cover the mouth of the trachea so that cold breath would not suddenly enter the lung, cool it, and the animal die suddenly if it entered the lung:`,
  '3#א': `["And esophagus, etc."] Thus wrote Rambam chapter 3 of Laws of Shechitah halachah 19: if the spinal column was broken and the majority of flesh with it, or it was torn from its back like a fish, or the majority of the trachea was severed, or the esophagus was punctured in any amount in the place fit for shechitah — behold it is neveilah while alive — thus is his language. And it is implied from his words that puncture of the esophagus is neveilah while alive even before slaughter; and so is implied the view of the Mechaber. However, it requires study: in chapter HaShochet (Chullin daf 32b) the gemara asks on this that Rava answered in the mishnah "these treifos are forbidden" it teaches "and some of them are neveilot" (meaning puncture of esophagus and majority severance of windpipe are neveilah) and "some are treifos" — let it also count one who made it a gistera neveilah; and it answers: when it teaches neveilah it means not that it imparts tumah while alive, for it does not teach imparting tumah while alive — thus puncture of esophagus and majority severance of windpipe are not neveilah while alive, but if slaughtered, even though slaughtered in the place of shechitah, it is invalidated by the shechitah and we call them [neveilah in that sense]. And even though it seems there that Rava's answer does not stand in the conclusion, nevertheless it seems there that this law — the default of the Talmud that puncture of esophagus and majority severance of windpipe are not neveilah while alive — is correct; and so is implied in Rashi there; and so in Semag, who wrote puncture of esophagus is treifah — thus it deals while alive, for it is only treifah alone. Even though Rashba in Teshuvot HaRishonim daf 27b and 3 holds that majority severance of windpipe is not even treifah while alive according to Rava — his words are difficult. See below siman 34 s.k. 3:`,
  '3#ב': `["Or puncture of esophagus-crop area, etc. — neveilah."] It is surprising, for we do not find anywhere that puncture of esophagus-crop area is neveilah; in Talmud and poskim it implies only treifah; and so from Rambam cited in the previous s.k.; and when he listed the eight treifos in chapter 1 he did not list what is neveilah and listed puncture of esophagus-crop area — from which it is not neveilah. Also the Mechaber himself wondered in several places on Rambam who wrote in chapter 3 "if slaughtered in esophagus-crop area — neveilah," for esophagus-crop area if punctured is treifah and not neveilah; even though I wrote in siman 20 s.k. 5 that he was not precise here, for certainly even though puncture of esophagus-crop area is only treifah, nevertheless since one slaughtered in the crop area it is invalidated by shechitah and there is no greater neveilah than this; nevertheless it is clear his view is that puncture of esophagus-crop area is only treifah, and here he wrote it is neveilah. And even though Taz in many places writes treifah where it is neveilah, because neveilah is in any case treifah — but treifah is certainly not neveilah; and how much more when the Mechaber himself in many places was precise about this. Also there are many halachic differences between treifah and neveilah even today — requires study:`,
  '4#א': `["And even if punctured not opposite one another."] And Lamed-Dalet to gizzard below siman 49: if punctured not opposite — kosher, for the gizzard rests calmly; but esophagus, since food and drink pass there regularly and it also breathes, sometimes the punctures align opposite one another and it is as a real puncture. Gemara:`,
  '4#ב': `["And all this does not apply, etc. — even if only the inner was punctured, etc."] Explanation of what he wrote nearby: if one of them was punctured — kosher, implying whichever was punctured, inner or outer — applies to this; and he says this is specifically when punctured through disease; but if there is concern it was punctured by thorn or needle, even if only the inner was punctured alone — treifah, for we are concerned perhaps the outer was also punctured; and esophagus has no examination from outside. But when only the outer was punctured we find it well kosher through examination from inside, as below seif 7. And that Shach wrote we are concerned perhaps punctured and esophagus has no examination from outside implies that from inside there is examination; and so is proven from Tosafot and Rosh from whom Shulchan Aruch brought this law — see there; and so in Darkei Moshe; and so wrote Taz and Bach. Bach understood what Shach wrote "even if only the inner was punctured — treifah" to mean certainly not that only the outer was punctured is treifah; therefore he entered with difficulty to reconcile Shach's view here; and the matter is simple as I wrote — no need to elaborate. Do not ask: if so, in this siman and at end of seif 8 and in siman 34 end of seif 9 Shach wrote if done through thorn or needle, for us who are not expert in examination of esophagus — treifah in every case and examination from inside does not help — say specifically when punctured by needle or thorn in an unknown place we are not expert even from inside, and that is the case at end of seif 23 and end of seif 8 and in siman 34 seif 9; but if a thorn or needle was inserted in esophagus from outside in a known place, examination of esophagus from the inside helps, for it is no worse than beit ha-kosot punctured from inside with a needle — kosher, as below siman 48; and where a needle is found in the body cavity — treifah, for we are concerned perhaps one of the organs puncturable in any amount was punctured and they have no examination, as below siman 51. Rather certainly, since the puncture in beit ha-kosot is in a known place, it has examination; and so esophagus. Now resolve what Mechaber wrote in seif 7 that regarding puncture too esophagus has no examination from outside but from inside; and in siman 51 wrote if needle found in body cavity — treifah, concerned perhaps punctured one of places puncturable in any amount and they have no examination — there we do not know at all where it was punctured and a puncture in any amount is not discernible; but here at least we know opposite the dirty place it was punctured and one can examine opposite the dirty place. And Shach's view: even in such a case there is no examination for puncture in any amount; but when thorn or needle inserted in esophagus in known place — kosher also for Shach, as in s.k. 7 — except this is called "not known" since one must examine along entire length and width of dirty place:`,
  '4#ג': `["But if there is concern, etc."] Meaning: not only where known punctured by thorn, but even if there is only concern it was punctured by thorn — treifah; and so in poskim: we require it be clear it came through disease; if not so, presumably by thorn:`,
  '5#א': `["And if they were reversed, etc."] Maharshal wrote: that which Rosh forbids when both red or both white means entirely red or entirely white; but partially we do not care; and if reversed in majority — requires study — end of his words. And that Rosh wrote "but here, since entirely flawed, it does not stand through the second" certainly implies only entirely; but not partially; nevertheless majority is as entirety in all Torah. Bach:`,
  '5#ב': `["And all the more if it has two esophagi or two tracheae, etc."] The reason is explicit in Rosh's responsum: anything extra is as if removed; and it is as if two esophagi or tracheae were removed; as Taz wrote end of siman 41: if two livers found — treifah — from that reason — see there:`,
  '6#א': `["If it is a bird, etc."] For its kashrut is through one sign; and even though l'chatchila one must slaughter two signs even for a bird, as above siman 21 — here, since it has permission only through one sign, it is considered b'dieved — so write poskim:`,
  '6#ב': `["And for us who are not expert."] In examination of derusah forever; as will be explained in siman 57 — see there:`,
  '8#א': `["We are not concerned for doubt of derusah, etc."] See siman 57 seif 13 and what is written there:`,
  '8#ב': `["But we are concerned for doubt of puncture, etc."] It implies Mechaber's view: even if punctured in unknown place — examination from inside. And Lamed-Dalet to what is written in siman 51: needle in body cavity — treifah, concerned perhaps punctured one of organs puncturable in any amount and they have no examination — there we do not know where punctured and puncture in any amount is not discernible; but here at least we know opposite dirty place it was punctured and can examine opposite dirty place. And Rama's view: even in such case no examination for puncture in any amount; but when thorn or needle inserted in esophagus in known place — kosher also for Rama, as in s.k. 7 — except this is called "not known" since must examine along entire length and width of dirty place:`,
  '8#ג': `["To examine the dirty place."] Meaning from inside opposite dirty place; for from outside — explained in seif 7 that regarding puncture too esophagus has no examination from outside. Mechaber follows Beit Yosef who brought Hagahot Ashiri in name of Or Zarua: nowadays we are not expert in examination; any bird that comes before us with neck dirty in blood — I forbid. And he wrote on this: it appears to me this is Beit HaGadol's view; but Rashi's view, as explained in siman 57 (that derusah has examination even nowadays) — nowadays too there is examination — end of his words. And in siman 57 end seif 8 he rules like Rashi; as written here in general in seif 6; therefore he also wrote here in general to examine dirty place. And even though Rashi and Mechaber hold puncture has no examination in esophagus — that is from outside because it is red; but from inside it is obvious they hold examination helps. This is simple; except in derusah some, due to haste, did not examine this well — see there. Shach also follows his view written in siman 57 and here that we are not expert in examination of derusah; therefore he wrote here like Hagahot Ashiri in name of Or Zarua and such is custom — clear:`,
  '9#א': `["Along its length or width and it is not stuck in it — kosher."] So Tur; and so Hagahot Or Zarua; and so Orach Chaim general rule 21 halachah 24. Reason in gemara: animals' way is to eat thorns; therefore as long as not stuck in it we do not establish presumption of flaw. And in several places chapter 3 Laws of Shechitah halachah 21 he wrote: specifically when thorn found along length — eating direction; but along width — we are concerned. Must say: there it deals when found in general and we do not know if it was stuck or not — we say presumably it was stuck. And so R' Yerucham netiv 15 ot 5 ch. 3; and Orach Chaim there:`,
  '9#ב': `["If there is no drop of blood on it from outside."] What is written here in Shulchan Aruch from Tur is an error; rather in Darkei Moshe so — see there Hagahot Maimoniyot chapter 3 Laws of Shechitah. Nevertheless requires study: also in Hagahot Maimoniyot he does not decide, for thus wrote R' Yitzchak: if there is drop of blood from outside — certainly the outer was punctured — Sefer HaTerumah — end of his words. And Rav's view there (in Darkei Moshe) is that it refers to "found," as printed; but difficult: for we do not find so in Sefer HaTerumah; therefore it appears it refers to "stuck," as language of "certainly outer was punctured" implies; otherwise should have said "certainly esophagus was punctured." Examine; and gemara teaches: with drop of blood from outside we are certainly concerned; no doubt at all, even for one who rules we are not concerned when stuck. And so in Sefer HaTerumah seif 14 and in Tosafot (daf 43b) in matter beginning "sat" — see there; requires study:`,
  '9#ג': `["But if it is stuck in it, etc."] Semak siman 141 wrote: explanation — inserted somewhat into inner skin of esophagus even if complete outside — end of his words. From his language it appears even if stuck and inner skin not punctured on both sides — called stuck; and so Bach:`,
  '9#ד': `["Even if there is no drop of blood."] Meaning: neither inside nor outside; and so proven from what Beit Yosef ruled like Rashba and his supporters. And Lamed-Dalet to beit ha-kosot: where no drop of blood — no concern, as below siman 48; esophagus is different because food and drink pass regularly there and wash through; but beit ha-kosot, where they eat and drink calmly — if it were while alive there would be drop of blood found — Ran; and so Rashba in Teshuvot HaRishonim daf 30a; R' Yerucham; and other poskim:`,
  '9#ה': `["Concern perhaps esophagus punctured and healed, etc."] Tur's language: healed — punctured and requires examination according to one who holds esophagus has examination. And one who holds healed — language of health: perhaps punctured and healed and examination does not help according to all — until here. It appears difficult why Mechaber needed reason of healed, since he ruled in seif 7 esophagus has no examination from outside — if so, simple to say we are concerned perhaps punctured even if not healed, for no examination from outside. It appears nevertheless he needed healed: otherwise examination would help when separating two membranes and seeing inner also not punctured through-and-through — then obvious outer not punctured at all; but if concerned perhaps healed — treifah; and so proven in R' Yerucham — see there; examine:`,
  '9#ו': `["And some permit if no drop of blood from outside."] Meaning: even if drop of blood inside — drop inside does not raise or lower; see Beit Yosef s.v. what our master wrote. But difficult: Shach ruled if concern only inner punctured by thorn — treifah, concerned perhaps outer also punctured; esophagus has no examination from outside. Can say: there Shach wrote Mechaber's view — concerned perhaps healed; and Shach himself so in s.k. 23; he did not write view of "some permit." However, he only informed that practicers of fattening geese relied on them. Difficult why above he gave reason concerned perhaps punctured and no examination from outside — even if there were examination, concerned perhaps healed, as Mechaber writes here. Can say Shach holds concern of healed is remote; we do not concern except for inner puncture, since can say also outer punctured and esophagus has no examination from outside; therefore even without drop inside, reason of perhaps healed makes treifah per Mechaber, as previous s.k. But if examination from outside existed, we would not concern for healed since not punctured before us; therefore above he gave reason no examination from outside: if only outer punctured by thorn or needle in known place — kosher through examination from inside, as s.k. 7 — we do not concern for healed since inner examination on white inner membrane, puncture in any amount discernible. Examine. Further resolve first difficulty: specifically here when thorn found stuck in esophagus — "some permit" if no drop outside; if outer also punctured it would be evident; therefore not concerned perhaps punctured; but when puncture found and no thorn, only concern punctured by thorn — worse, for if thorn before us it would puncture outward; therefore must distinguish: Shach in end seif 23 and this seif 8 and siman 34 end seif 4 concerned perhaps esophagus punctured from outside to inside and examination from inside does not help; here examination helps even from outside despite rule no examination from outside because red — since thorn found stuck, better: if punctured would be evident outside; by law should be permitted without examination, not concerned perhaps punctured since thorn stuck before us; to be stringent requires examination; similar to above siman 24: sign of slaughter dangling, signs not grasped — kosher through examination; impossible dangling become slaughtered — so in several places examination is only stringency — see siman 48 s.k. 32 and 33:`,
  '9#ז': `["If not punctured on both sides or no drop of blood, etc."] Simple: printing error; must read: if not punctured on both sides and no drop outside; and so explicitly Darkei Moshe; and so Bach:`,
  '9#ח': `["And it would be better, etc."] Shach speaks of practicers who fatten geese and are lenient when thorn sits in esophagus; much to examine; do not be lenient, for main view of Mechaber and supporters: even without drop, even inside — treifah when thorn stuck. If so, better for them not to examine and rely on majority when found stuck, if not punctured both sides and no drop outside — greater leniency; and here certainly d'oraisa prohibition, for majority of poskim hold like Mechaber: even without drop inside or outside — treifah; and so Maharshal siman 51 ot 5. But Or Zarua: here, since thorn stuck before us — called known place; but above deals with concern punctured in unknown place, as written there. And even R' Yehuda wrote: thorn found stuck not called known place — perhaps thorn punctured above and food/drink brought it down, and puncture not where thorn stands — Beit Yosef; but Shach does not concern for this; this is called known place. Shach: both not kosher; what he brought "some permit" only to inform practicers relied on them; his view: since lung adhesions more common — do not rely on majority; examination required; as below siman 39 regarding lung; and where thorn found stuck in esophagus — law agreed per Mechaber, as s.k. 21; and so explicitly Darkei Moshe as explained; and Taz only brought Mechaber's words; Bach cried like a herald against custom of fattening geese — see there; and responsum Maharam of Lublin siman 21: community enacted to examine esophagi; later heads thrown away without examining esophagi — kosher b'dieved; see there at length:`,
});

// --- turei-zahav (21) ---
patchFile('siman_033/turei-zahav/part-001.txt', 'turei-zahav', {
  '1#א': `Lower cheek kosher. Tur wrote here on Rambam; and I wrote, etc. — he did not write this as a difficulty on Rambam interpreting the sugya that majority uprooted in signs is kosher — apart from where signs depend on it; and law of removal of signs — see siman 24:`,
  '1#ב': `Hamara and haleta. Explanation: they insert food for it into the swallowing chamber until a place it cannot return — called hamara; and where it can return — called haleta — chapter Mi she'Hechshich:`,
  '3#_': `Into its cavity. The same for anything that disqualifies through puncture that has a cavity — not disqualified until punctured into cavity; if no cavity — needs complete opening — Tosafot, Rashba, Ran on mishnah of these treifos:`,
  '4#א': `Not opposite one another. Since food passes there and compresses and stretches it, sometimes punctures happen to align:`,
  '4#ב': `It is possible they align. Maharshal wrote: even if punctures far apart, not possible to compress so much — nevertheless forbidden, for there is no measure how close they must be; one does not give sages' words measures unless fixed matter — end of his words:`,
  '4#ג': `When clear puncture came from disease. And on outer — no disease discernible — so Tosafot chapter HaShochet; and so Rosh — see what I wrote on this in siman 51 with heavenly support:`,
  '4#ד': `Only inner. And all the more if only outer punctured alone — so Orach Chaim general rule 21:`,
  '5#א': `And if reversed, etc. Reason in Tur: one is flawed and the other protects it — not like small puncture where friend protects; but here both entirely flawed — not sustained by second. Ran beginning siman 51 wrote: Rashi's "if reversed — treifah" means inner reddened through admonition and treifah, for we say it is derusah as below — found two drops of blood and treifah; Maharach z"l learned from this: even if only part of inner reddened — treifah, for we say derusah; even if predator not established before us. And he further wrote: even if redness found opposite intestines — treifah from this reason — end. Strange words — to cause loss of Jewish money wherever red point found in any flesh of animal saying derusah; if so, asmachta of blood congealed from blow in siman 57 — how find it; he says not where we saw strike, but from congealed blood we say from blow; and in siman 57 we forbid reddened flesh opposite intestines for derusah where doubt of derusah without seeing lion among animals; but without that, no; and siman 57 seif 14: even if neck torn — do not attribute to derusah if predator not seen between them; kal v'chomer for redness in esophagus. And in Teshuvot HaRishonim house 2 sha'ar 2 Rashi: if one reversed, e.g. both red — kosher, for only one corrupted — end; Rashi himself did not concern for derusah from redness; his words would contradict; rather Ran deals only where without that doubt of derusah we saw lion — relies on what we say below found two drops; there doubt of derusah; Rashba responsum 277: some concern doubt of derusah only with clear evidence — end. I had dispute with Maharach; presented to Maharam Yafe and rabbis — none concern for this at all; we permit daily when slight redness inside esophagus:`,
  '5#ב': `Both red. Tur: one flawed, friend protects — not like small puncture; here both entirely flawed — not sustained. Maharshal: entirely red or white; partially we do not care; majority — requires study. Shach: Rosh's language implies majority as entirety in all Torah; Bach so rules. Darkei Moshe: only when both entirely red need entirety or majority; but actual exchange one red one white — treifah even slightly. Maharshal questioned why here if both red or white one flawed and second does not protect unlike lung siman 36 where even entire upper membrane peeled — kosher; Darkei Moshe sensed and answered: esophagus membranes different — always moving with food — cannot stand on one membrane; if so even partial reversal treifah since only one membrane there when food arrives and esophagus punctured anywhere. Can answer: worse when second membrane absent entirely; but practically do not rely to be lenient — see siman 36 where I wrote another answer:`,
  '5#ג': `Or white. Maharshal siman 51 ot 3: Rashba permits if one alone reversed; Tosafot uncertain — fit to heed; forbid only both red, for one is flawed; but both white — what flaw; disqualification of appearances only in lung — whence add treifos; and so Or Zarua as Tosafot R' Yitzchak Shirlian explained before R' Yitzchak — end:`,
  '6#_': `Examine trachea. Explanation: tear skin slightly first, then can examine trachea at shechitah place:`,
  '7#_': `Regarding puncture too. Reason in Rashi chapter HaShochet (Chullin 28): perhaps blood drop entered puncture — therefore not discernible outside since all red:`,
  '8#א': `And neck dirty with blood. Rashi: neck torn outside — if not torn, only dirt after shechitah around esophagus inside — no concern, even for us:`,
  '8#ב': `Not concerned for doubt. Since no predator before us; as siman 57 seif 14. Tur wrote two interpretations on healed and practical difference whether examination after membrane from blow helps:`,
  '9#א': `And not stuck — kosher. Unlike needle in body cavity concerned for inner organ — here perhaps never punctured at all; as siman 31 seif 3 regarding worm in nostril:`,
  '9#ב': `If no drop of blood. Tur does not imply so; Hagahot Maimoniyot chapter 3 Laws of Shechitah: R' Yitzchak — if drop outside — certainly outer punctured — Sefer HaTerumah. From "drop outside" on esophagus: wherever drop on esophagus even not opposite thorn — treifah, perhaps punctured there and returned; also implies: only when found outside treifah; but found inside — permitted. And Or Zarua: all the more inside — Hagahot Maimoniyot follows Sefer HaTerumah; Ba'al Sefer HaTerumah permits even thorn stuck as Hagahot Ashiri in his name siman 51 — rules like Ula — among "some permit" Rama brings; there no prohibition of drop except outside as Rama there. Indeed from gemara seems forbid even found with drop inside alone from Rav Kahana "sat was stated; found not" — Ula permits; all animals of baraita eat thorns — do they all have drop inside; perhaps teaches even with drop inside permitted; or he does not care about drop — then also if outside not forbidden unless certain. And Orach Chaim general rule 91: thorn found in esophagus cavity along length or width — kosher even along width, no flaw seen, lying like a bar — so in Sefer HaParnas; not concerned perhaps healed in esophagus unless clear flaw inside — thus forbid even clear inside alone; therefore forbid found lying with drop inside; and all the more outside as above:`,
  '9#ג': `Even if no drop of blood. And Lamed-Dalet to needle in beit ha-kosot siman 48 and gizzard siman 49: prohibition only with drop — different; esophagus food washes — perhaps they moved blood — Ran; so soft:`,
  '9#ד': `And thus practiced to be lenient, etc. Explanation: in his city they were stringent on one side and lenient on other: per majority both membranes not punctured completely; sometimes punctured; if not punctured — flawed from fattening; all flaw as punctured — simple in places; common though not majority; minority frequent like lung adhesions — therefore stringent to examine; lenient on one side: if punctured from one wind — not concerned perhaps also second and healed — like "some permit" Rama mentioned; Rama on this: do not rely on "some permit" since d'oraisa; better not examine and rely on majority per all; than examine and be lenient where flaw. Because all places fatten — learn merit: permitted per all when flaw did not reach outer; when inner flawed, outer not — full permission when no flaw on outer. When examining geese we see all punctures on inner from fattening disease; since flaw did not reach outer — permitted to all who disagree only inner skin punctured without flaw before us; unlike when we see flaw ruled inner and not outer — why concern perhaps punctured and healed since inner did not heal — certainly full permission when no flaw on outer. Even if partial flaw on outer — no prohibition, for Tosafot Rosh "on outer no disease discernible" means no flaw at all on outer; if flaw ruled part of outer we follow reason: where ruled inner and not outer — ruled on inner; outer itself also not ruled — end of Tosafot intent. Therefore even if flaw ruled part of outer — no prohibition even if majority ruled; as gizzard siman 49 we permit even if little outer membrane remains. All the more esophagus: permit even if only minority outer remains if no flaw there per examiner — eyes of teacher. Israel's custom has basis; heaven forbid all stumbled in d'oraisa; nevertheless God-fearing should warn household to fatten birds gently with small pieces avoiding doubt — as I think:`,
  '9#ה': `If not punctured on both sides or no drop of blood. This "or" is printing error; must be "and" no drop; and so explicitly Darkei Moshe:`,
  '11#א': `Crop removed. Tur in name of geonim' responsa: proof from "roof of crop judged like esophagus" — not like Rabbi who says even if removed; Rashba questioned: perhaps Rabbi permits removal only below roof while roof exists; Beit Yosef answered geonim mean: since place exists where even puncture alone treifah, unreasonable elsewhere kosher if entirely removed; his words strange — we do not compare treifos; cut here and lives, etc. It appears geonim: "roof of crop" — law like esophagus, not "punctured treifah"; why tie to esophagus — must say roof very serious, law like esophagus; crop itself also severity; thus treifah if removed at least:`,
  '11#ב': `Flesh punctured, etc. Doubt perhaps belongs to gizzard and its puncture in any amount:`,
});

// --- baer-heitev (17) ---
patchFile('siman_033/baer-heitev/part-001.txt', 'baer-heitev', {
  '1#_': `Kosher. And it can live, etc. Mirror means inserting into swallowing chamber until cannot return; where can return — haleta. Darkei Moshe: if upper beak of bird removed — treifah to Rambam like upper cheek — one reason. Shach: matter of no removal of signs — meat on signs torn from cheek. Rokeach: tongue until tonsil kosher; with tonsil treifah. Pri Chadash questioned adding treifos:`,
  '3#_': `Neveilah. Anything disqualifying through puncture with cavity — not disqualified until into cavity; if no cavity — complete opening needed (Maharam of Rothenburg). Shach rules puncture of esophagus while alive only treifah not neveilah; left Mechaber's words on esophagus-crop as neveilah in requires study — he holds only treifah:`,
  '4#א': `Forbidden. Food entered and compressed and stretched; sometimes punctures align. Even thick sealing does not help — Rashi; in all punctures sealing does not avail:`,
  '4#ב': `One another. Taz in name Maharshal: even far punctures forbidden — no measure for sages' words:`,
  '4#ג': `From outside. Shach: from inside examination; do not challenge siman 23 and this seif 8 — Rama: thorn/needle for us not expert — treifah, examination inside does not help — specifically unknown place; known place — examination from inside helps like beit ha-kosot siman 48; needle in body cavity treifah; Bach: known place — examination from inside even for us; dirty neck not known place; Shach: "if concern" — even mere concern of thorn treifah until clear disease:`,
  '5#א': `Treifah. Shach Maharshal: both red or white — entirely; partial — no; majority reversed requires study; majority as entirety; Bach; Darkei Moshe: both red need all or majority; actual color exchange even slight treifah (Maharam of Rothenburg). Taz Bach: inner reddened treifah as derusah even predator not seen; disputes Taz; daily permit slight redness in esophagus. Taz questions lung siman 36; answers worse without second membrane; one skin removed from entire esophagus would be kosher but not relied; see siman 36; Mechaber both white — Taz disagrees, only both red treifah, do not add treifos:`,
  '5#ב': `Treifah. Extra as removed; connected top and bottom only split in middle — Rama and Pri Chadash permit like two maros siman 42. Some male geese trachea splits in two near body with button at split — kosher, majority; Orach Chaim responsa permits punctures; Kenesset HaGedolah Nekudat HaKesef: female goose trachea often splits upward — slaughterers testify:`,
  '7#_': `From inside. Perhaps blood drop in puncture — not seen outside all red; slaughter only trachea then check esophagus; bird l'chatchila two signs — here only one sign b'dieved (Maharam of Rothenburg):`,
  '8#א': `In blood. Taz: specifically neck torn outside; dirt after shechitah around esophagus inside — no concern even for us:`,
  '8#ב': `Dirty place. From inside; outside no examination even for puncture. Shach: even unknown place has examination unlike needle in body cavity; known place Rama permits even puncture in any amount; thorn/needle known place kosher; see end seif 4:`,
  '9#א': `Kosher. Shach: Hagahot Maimoniyot only along length kosher, width concerned if unknown stuck; here known not stuck kosher. Port found stuck strong in esophagus eating half flesh — Pri Chadash permits; Chokhmat Shlomo agrees; Pri Megadim leans stringent — stay siman 3; slaughtered food between trachea and esophagus treifah — cannot enter without puncture; minority esophagus slipped from connection — rely since no puncture seen — Radbaz siman 193; see Kenesset HaGedolah:`,
  '9#ב': `From outside. Taz forbids even found lying with drop inside, all the more outside; difficult from Ula; Maharam of Rothenburg. Shach wonders on Rama: forbid only if certainly stuck — then drop outside certainly punctured, not mere concern; Rama "if no drop" scribe error — refers to "some permit" when stuck:`,
  '9#ג': `Forbidden. Shach: even if inner skin not punctured both sides — called stuck:`,
  '9#ד': `Discernible. Pri Chadash: do not concern healed — how rely healthy lung inflation where flaw concern puncture and membrane; Shach: even separating membranes inner not through-and-through; unlike beit ha-kosot no drop — esophagus food washes:`,
  '9#ה': `From outside. Scribe error: and not punctured both sides and no drop outside (Taz). Shach: drop inside does not raise/lower; Taz and acharonim forbid drop inside — perhaps also outside not seen; for emphasis outside — even only outer treifah. Difficult seif 4 Rama concern inner thorn — Shach above; say Rama disease healed concern; here known place thorn stuck; above unknown; bubbles between skins treifah; thick spots in neck skins; after peeling feathers stretched — outer no flaw — forbid all geese (Chokhmat Binyamin question 44):`,
  '9#ו': `Flaw. Shach: Rama does not lenient like "some permit"; better not examine; rule like Mechaber even no drop inside when stuck; Taz Bach forbid fattening entirely; Taz gives basis to custom — no flaw no concern; heaven forbid stumbling; warn gentle fattening; Maharam Lublin responsum community enacted examine esophagi then threw heads without examine — kosher b'dieved; cover blood before examine rely majority SA siman 61; geese fattened in dough rings dried in oven — esophagus blisters/scratches — if no outer flaw permit Pri Chadash; responsa Bayit Yehezkel; Tzitz Eliezer; second thread; responsa Shvut Yaakov question 49:`,
  '11#_': `Punctured. Perhaps gizzard; Beit Yehudah: needle/hardness in intestine no visible puncture — permitted safek safek; if stuck treifah Pri Chadash:`,
});

